                H("Correction majorant"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The majorant is pi^2/(6*(1-pi^2/(6*s^2))). Its denominator is positive for s at least pi."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("entropy-kernel-correction-upper"),
                DeclarationHandle.Create("D5/S3/Arith/Robin/Analytic/OmegaSecond/Entropy.kernel_correction_upper"),
